#!/bin/bash
# Warp notification utility using OSC escape sequences.
# Usage: warp-notify.sh <title> <body>
#
# For structured Warp notifications, title should be "warp://cli-agent"
# and body should be a JSON string matching the cli-agent notification schema.

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
source "$SCRIPT_DIR/should-use-structured.sh"

# Only emit notifications when we've confirmed the Warp build can render them.
if ! should_use_structured; then
    exit 0
fi

TITLE="${1:-Notification}"
BODY="${2:-}"

# OSC 777 format: \033]777;notify;<title>;<body>\007
SEQ=$(printf '\033]777;notify;%s;%s\007' "$TITLE" "$BODY")

fail_transport() {
    # 这是稳定诊断码，不是 UI 文案；调用方可按码分类失败。
    printf '%s\n' "infinishell_codex_hook_transport_error: $1" >&2
    exit 1
}

open_terminal() {
    local candidate="$1"
    # 只接受 /dev 下的真实字符终端，拒绝普通文件、链接和控制字符。
    case "$candidate" in
        /dev/*) ;;
        *) return 1 ;;
    esac
    case "$candidate" in
        *[![:print:]]*|*' '*|*'..'*) return 1 ;;
    esac
    [ ! -L "$candidate" ] && [ -c "$candidate" ] || return 1
    exec 9>"$candidate" || return 1
    if [ ! -t 9 ]; then
        exec 9>&-
        return 1
    fi
}

open_ancestor_terminal() {
    local pid="$PPID" command_name tty_name candidate attempt
    for attempt in 1 2 3 4 5 6; do
        case "$pid" in
            ''|*[!0-9]*|0|1) return 1 ;;
        esac
        command_name=$(ps -o comm= -p "$pid" 2>/dev/null) || return 1
        command_name="${command_name##*/}"
        if [ "$command_name" = "codex" ] || [[ "$command_name" == codex-* ]]; then
            tty_name=$(ps -o tty= -p "$pid" 2>/dev/null) || return 1
            tty_name="${tty_name//[[:space:]]/}"
            case "$tty_name" in
                ''|'??'|'?') ;;
                *)
                    candidate="/dev/$tty_name"
                    open_terminal "$candidate" && return 0
                    ;;
            esac
        fi
        pid=$(ps -o ppid= -p "$pid" 2>/dev/null) || return 1
        pid="${pid//[[:space:]]/}"
    done
    return 1
}
case "$(uname -s)" in
        MINGW*|MSYS*)
            # Git Bash 无 /dev/tty 时，仍可通过已附着的 Windows 控制台输出。
            windows_root="${SYSTEMROOT:-${SystemRoot:-}}"
            windows_root="${windows_root//\\//}"
            powershell="$windows_root/System32/WindowsPowerShell/v1.0/powershell.exe"
            if [ -n "$windows_root" ] && [ -f "$powershell" ]; then
                (printf '%s' "$SEQ" | "$powershell" -NoLogo -NoProfile -NonInteractive -EncodedCommand ) || fail_transport "windows_console_write_failed"
            else
                fail_transport "windows_console_not_found"
            fi
            ;;
        *)
            tmux_transport=false
            if [ -n "${TMUX:-}" ]; then
                case "${TMUX_PANE:-}" in
                    %*[!0-9]*|%|'') fail_transport "invalid_tmux_pane" ;;
                    %*) ;;
                    *) fail_transport "invalid_tmux_pane" ;;
                esac
                command -v tmux >/dev/null 2>&1 || fail_transport "tmux_not_found"
                tty_target=$(tmux display-message -p -t "$TMUX_PANE" '#{pane_tty}') \
                    || fail_transport "tmux_pane_query_failed"
                open_terminal "$tty_target" || fail_transport "invalid_tmux_pane_tty"
                tmux_transport=true
            elif [ -n "${SSH_TTY:-}" ]; then
                open_terminal "$SSH_TTY" || fail_transport "invalid_ssh_tty"
            elif open_terminal /dev/tty; then
                :
            elif ! open_ancestor_terminal; then
                fail_transport "terminal_not_found"
            fi
            if [ "$tmux_transport" = true ]; then
                # tmux 需要 DCS 透传封套，内部每个 ESC 都必须双写；不修改用户透传配置。
                ESC=$'\033'
                SEQ="${SEQ//$ESC/$ESC$ESC}"
                SEQ=$(printf '\033Ptmux;%s\033\\' "$SEQ")
            fi
            printf '%s' "$SEQ" >&9 || fail_transport "terminal_write_failed"
            exec 9>&-
            ;;
    esac
